    const name = config.provider === "codex" ? "Codex" : "Copilot";
    try { const status = await api(`/api/librarian/status?provider=${config.provider}`); state = status.installed ? "green" : "red"; title = status.installed ? `${name} ${text("aiIndicatorConnected")}` : `${name} ${text("aiIndicatorNotWorking")}`; body = status.installed ? `${providerNames[config.provider]} ${text("aiIndicatorReadyLibrarian")}` : (status.error || text("aiIndicatorAuthorizeCli").replace("{name}", name)); } catch { state = "red"; title = `${name} ${text("aiIndicatorUnavailable")}`; body = text("aiIndicatorCheckCli"); }
