function wireCanvas() {
  const wrap = document.querySelector("#canvas-wrap"), canvas = document.querySelector("#knowledge-canvas");
  if (!wrap || !canvas) return;
  let scale = 1, dragging = false, pointerId = null, startX = 0, startY = 0, originX = 0, originY = 0, frame = 0;
  const range = document.querySelector("#map-zoom-range");
  const paint = () => {
    frame = 0;
    canvas.style.transform = `translate3d(${originX}px,${originY}px,0) scale(${scale})`;
    wrap.classList.toggle("zoom-far", scale < .42);
    wrap.classList.toggle("zoom-universe", scale < .2);
    const zoom = document.querySelector("#map-zoom");
    if (zoom) zoom.textContent = `${Math.round(scale * 100)}%`;
    if (range) range.value = String(Math.round(scale * 100));
  };
  const schedulePaint = () => { if (!frame) frame = requestAnimationFrame(paint); };
  // center initially
  setTimeout(() => {
    try {
      originX = (wrap.clientWidth - canvas.offsetWidth * scale) / 2;
      originY = (wrap.clientHeight - canvas.offsetHeight * scale) / 2;
      schedulePaint();
    } catch(e) {}
  }, 0);
  wrap.onpointerdown = (event) => { if (event.button !== 0 || event.target.closest(".map-node,.map-topic-node,.canvas-toolbar")) return; dragging = true; pointerId = event.pointerId; startX = event.clientX - originX; startY = event.clientY - originY; wrap.setPointerCapture(pointerId); wrap.classList.add("dragging"); };
  wrap.onpointermove = (event) => { if (!dragging || event.pointerId !== pointerId) return; originX = event.clientX - startX; originY = event.clientY - startY; schedulePaint(); };
  const stopDragging = () => { dragging = false; pointerId = null; wrap.classList.remove("dragging"); };
  wrap.onpointerup = stopDragging; wrap.onpointercancel = stopDragging; wrap.onpointerleave = (event) => { if (dragging && event.buttons === 0) stopDragging(); };
  wrap.onwheel = (event) => {
    event.preventDefault();
    const nextScale = Math.max(.08, Math.min(4, scale * (event.deltaY < 0 ? 1.12 : .88)));
    const bounds = wrap.getBoundingClientRect();
    const pointerX = event.clientX - bounds.left;
    const pointerY = event.clientY - bounds.top;
    const canvasX = (pointerX - originX) / scale;
    const canvasY = (pointerY - originY) / scale;
    originX = pointerX - canvasX * nextScale;
    originY = pointerY - canvasY * nextScale;
    scale = nextScale;
    schedulePaint();
  };
  const setScale = (value) => { scale = Math.max(.08, Math.min(4, value)); schedulePaint(); };
  if (range) range.oninput = () => setScale(Number(range.value) / 100);
  document.querySelector("#map-reset").onclick = () => {
    scale = 1;
    originX = (wrap.clientWidth - canvas.offsetWidth) / 2;
    originY = (wrap.clientHeight - canvas.offsetHeight) / 2;
    schedulePaint();
  };
}
